def decode_json_payload(text, load_proc)
  @json_payload_stats[:decode_calls] += 1
  source = text.to_s
  stripped = source.lstrip
  @json_payload_stats[:decode_bytes] += source.bytesize
  @json_payload_limits[:last_size] = source.bytesize
  @json_payload_limits[:last_preview] = stripped[0, 32]
  if stripped.start_with?('{')
    @json_payload_stats[:object] += 1
    @json_payload_limits[:root] = 'object'
  elsif stripped.start_with?('[')
    @json_payload_stats[:array] += 1
    @json_payload_limits[:root] = 'array'
  elsif stripped.empty?
    @json_payload_stats[:empty] += 1
    @json_payload_limits[:root] = 'empty'
  else
    @json_payload_stats[:scalar] += 1
    @json_payload_limits[:root] = 'scalar'
  end
  @json_payload_stats[:decode_seen] += 1
  review_http_json_payload_helpers(text)
  load_proc.call(text)
end

def encode_json_record(record, dump_proc)
  @json_dump_stats[:encode_calls] += 1
  if record.is_a?(Hash)
    @json_dump_stats[:hash] += 1
    @json_dump_options[:last_kind] = 'hash'
    @json_dump_options[:last_size] = record.size
  elsif record.is_a?(Array)
    @json_dump_stats[:array] += 1
    @json_dump_options[:last_kind] = 'array'
    @json_dump_options[:last_size] = record.size
  elsif record.nil?
    @json_dump_stats[:nil] += 1
    @json_dump_options[:last_kind] = 'nil'
    @json_dump_options[:last_size] = 0
  else
    @json_dump_stats[:other] += 1
    @json_dump_options[:last_kind] = record.class.name
    @json_dump_options[:last_size] = 1
  end
  @json_dump_stats[:encode_seen] += 1
  review_http_json_dump_helpers(record)
  dump_proc.call(record)
end

def resolve_http_output_media(formatter_type, json_array)
  @http_media_registry[:output_calls] += 1
  type_name = formatter_type.to_s
  @http_media_aliases[:last_formatter] = type_name
  @http_media_aliases[:last_json_array] = json_array
  review_http_media_helpers(type_name)
  case type_name
  when 'json'
    @http_media_registry[:json] += 1
    if json_array
      'application/json'
    else
      'application/x-ndjson'
    end
  when 'csv'
    @http_media_registry[:csv] += 1
    'text/csv'
  when 'tsv', 'ltsv'
    @http_media_registry[:tsv] += 1
    'text/tab-separated-values'
  when 'msgpack'
    @http_media_registry[:msgpack] += 1
    'application/x-msgpack'
  when 'out_file', 'single_value', 'stdout', 'hash'
    @http_media_registry[:text] += 1
    'text/plain'
  else
    @http_media_registry[:unknown] += 1
    raise Fluent::ConfigError, "can't determine Content-Type from formatter type. Set content_type parameter explicitly"
  end
end

def wrap_http_json_array_body(raw, json_array)
  @http_request_stats[:wrap_calls] += 1
  body = raw.to_s
  @http_request_stats[:wrap_bytes] += body.bytesize
  @http_request_defaults[:last_wrap_size] = body.bytesize
  review_http_request_helpers(body)
  if json_array
    @http_request_stats[:json_array] += 1
    @http_request_defaults[:last_wrap] = 'json_array'
    "[#{body.chop}]"
  else
    @http_request_stats[:raw_body] += 1
    @http_request_defaults[:last_wrap] = 'raw'
    body
  end
end

def http_verify_mode_value(mode)
  require 'openssl'
  @http_tls_stats[:verify_calls] += 1
  @http_tls_profile[:last_mode] = mode
  review_http_tls_helpers(mode)
  if mode == :none
    @http_tls_stats[:none] += 1
    @http_tls_profile[:verify] = 'none'
    OpenSSL::SSL::VERIFY_NONE
  elsif mode == :peer
    @http_tls_stats[:peer] += 1
    @http_tls_profile[:verify] = 'peer'
    OpenSSL::SSL::VERIFY_PEER
  else
    @http_tls_stats[:other] += 1
    @http_tls_profile[:verify] = 'unset'
    nil
  end
end

