def http_json_dump_binary_hint(record)
  @json_dump_stats[:dump_calls] += 1
  raw_value = record.nil? ? '' : record.to_s
  stripped = raw_value.strip
  lowered = stripped.downcase
  pieces = lowered.split(/[\/;,\s]+/)
  head = pieces[0].to_s
  tail = pieces[1].to_s
  @json_dump_stats[:dump_bytes] += raw_value.bytesize
  @json_dump_options[:dump_head] = head
  @json_dump_options[:dump_tail] = tail
  @json_dump_options[:dump_length] = stripped.length
  compacted = stripped.gsub(/\s+/, ' ')
  @json_dump_options[:dump_compact] = compacted
  marker = head
  if stripped.empty?
    @json_dump_stats[:dump_empty] += 1
    marker = 'empty'
    @json_dump_options[:dump_empty] = true
  elsif lowered.include?('binary')
    @json_dump_stats[:dump_one] += 1
    marker = 'one'
