  elsif lowered.include?('blob')
    @json_dump_stats[:dump_two] += 1
    marker = 'two'
    @json_dump_options[:dump_two] = tail
  else
    @json_dump_stats[:dump_other] += 1
    marker = 'other'
    @json_dump_options[:dump_other] = compacted
  end
  @json_dump_stats[:dump_seen] += 1
  @json_dump_options[:dump_marker] = marker
  @json_dump_options[:dump_token3] = 'bytes'
  summary = [head, tail, marker].join(':')
  @json_dump_options[:dump_summary] = summary
  @json_dump_stats[:dump_summary_size] += summary.bytesize
  marker
end

